ALTER TABLE email_outbox ADD COLUMN html text NOT NULL DEFAULT '';
ALTER TABLE email_outbox ADD COLUMN user_id uuid REFERENCES users(id);
ALTER TABLE email_outbox ADD COLUMN kind text NOT NULL DEFAULT 'transactional';
ALTER TABLE email_outbox ADD COLUMN attempts integer NOT NULL DEFAULT 0;
ALTER TABLE email_outbox ADD COLUMN next_attempt_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE email_outbox ADD COLUMN lease_until timestamptz;
ALTER TABLE email_outbox ADD COLUMN provider_id text;
ALTER TABLE email_outbox ADD COLUMN last_error text;
ALTER TABLE email_outbox ADD COLUMN event_key text UNIQUE;
ALTER TABLE email_outbox ADD COLUMN expires_at timestamptz;
ALTER TABLE sessions ADD COLUMN user_agent text NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN last_seen_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE customer_service_config(id integer PRIMARY KEY CHECK(id=1),started_at timestamptz NOT NULL DEFAULT now());
INSERT INTO customer_service_config(id) VALUES(1);
CREATE TABLE processed_customer_events(event_id uuid PRIMARY KEY REFERENCES audit_events(id));
CREATE TABLE notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),event_key text NOT NULL UNIQUE,title text NOT NULL,body text NOT NULL,reference_id text,kind text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_owner_idx ON notifications(user_id,created_at);
CREATE TABLE support_tickets(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),subject text NOT NULL,category text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','waiting_customer','waiting_staff','resolved','closed')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('normal','high')),transaction_id uuid,assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_messages(id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_tickets(id),author_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,attachment_ids jsonb NOT NULL DEFAULT '[]',staff_reply boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_owner_idx ON support_tickets(user_id,updated_at);
ALTER TABLE private_files DROP CONSTRAINT private_files_purpose_check;
ALTER TABLE private_files ADD CONSTRAINT private_files_purpose_check CHECK(purpose IN('kyc','deposit','payout','inventory','physical','support'));
ALTER TABLE private_files ADD COLUMN purged_at timestamptz;
CREATE TABLE mfa_credentials(user_id uuid PRIMARY KEY REFERENCES users(id),secret_encrypted text NOT NULL,enabled boolean NOT NULL DEFAULT false,last_counter bigint NOT NULL DEFAULT -1,recovery_hashes jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE withdrawal_addresses(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),label text NOT NULL,route_id text NOT NULL REFERENCES crypto_settings(route_id),address text NOT NULL,memo text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,route_id,address,memo));
ALTER TABLE kyc_cases ADD COLUMN document_expires_on date;
ALTER TABLE kyc_cases ADD COLUMN renewal_required boolean NOT NULL DEFAULT false;
ALTER TABLE kyc_cases ADD COLUMN legal_hold boolean NOT NULL DEFAULT false;
ALTER TABLE kyc_cases ADD COLUMN deletion_requested_at timestamptz;
CREATE TABLE kyc_history(id uuid PRIMARY KEY,case_id uuid NOT NULL REFERENCES kyc_cases(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO kyc_history(id,case_id,actor_id,action,snapshot) SELECT id,id,coalesce(reviewer_id,user_id),'imported',jsonb_build_object('status',status,'documentType',document_type,'documentIds',document_ids,'reason',reason) FROM kyc_cases;
ALTER TABLE physical_gold_requests ADD COLUMN carrier text NOT NULL DEFAULT '';
ALTER TABLE physical_gold_requests ADD COLUMN tracking_url text;
ALTER TABLE physical_gold_requests ADD COLUMN address_confirmed_at timestamptz;
ALTER TABLE physical_gold_requests ADD COLUMN address_confirmed_by uuid REFERENCES users(id);
ALTER TABLE physical_gold_requests ADD COLUMN allocation_reference text;
ALTER TABLE physical_gold_requests ADD COLUMN delivered_at timestamptz;
ALTER TABLE physical_gold_requests ADD COLUMN acknowledged_at timestamptz;
CREATE TABLE transaction_documents(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),transaction_id uuid NOT NULL,stage text NOT NULL,number text NOT NULL UNIQUE,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_id,stage));
